type redeemcodePaginateArgs struct {
	first, last   *int
	after, before *Cursor
	opts          []RedeemCodePaginateOption
}

func newRedeemCodePaginateArgs(rv map[string]any) *redeemcodePaginateArgs {
	args := &redeemcodePaginateArgs{}
	if rv == nil {
		return args
	}
	if v := rv[firstField]; v != nil {
		args.first = v.(*int)
	}
	if v := rv[lastField]; v != nil {
		args.last = v.(*int)
	}
	if v := rv[afterField]; v != nil {
		args.after = v.(*Cursor)
	}
	if v := rv[beforeField]; v != nil {
		args.before = v.(*Cursor)
	}
	if v, ok := rv[orderByField]; ok {
		switch v := v.(type) {
		case map[string]any:
			var (
				err1, err2 error
				order      = &RedeemCodeOrder{Field: &RedeemCodeOrderField{}, Direction: entgql.OrderDirectionAsc}
			)
			if d, ok := v[directionField]; ok {
				err1 = order.Direction.UnmarshalGQL(d)
			}
			if f, ok := v[fieldField]; ok {
				err2 = order.Field.UnmarshalGQL(f)
			}
			if err1 == nil && err2 == nil {
				args.opts = append(args.opts, WithRedeemCodeOrder(order))
			}
		case *RedeemCodeOrder:
			if v != nil {
				args.opts = append(args.opts, WithRedeemCodeOrder(v))
			}
		}
	}
	if v, ok := rv[whereField].(*RedeemCodeWhereInput); ok {
		args.opts = append(args.opts, WithRedeemCodeFilter(v.Filter))
	}
	return args
}

